import sqlite3
import requests

DB_PATH = "projects.db"


def _fetch_rows(sprint_id):
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        sprint = conn.execute(
            "SELECT id, name, start_date, end_date FROM sprints WHERE id = ?",
            (sprint_id,),
        ).fetchone()
        tasks = conn.execute(
            "SELECT id, title, status, points, blocked FROM tasks WHERE sprint_id = ?",
            (sprint_id,),
        ).fetchall()
    finally:
        conn.close()
    return sprint, tasks


def post_sprint_summary_to_slack(sprint_id, webhook_url, include_blockers=False):
    sprint, tasks = _fetch_rows(sprint_id)
    if sprint is None:
        return {"ok": False, "error": f"Sprint {sprint_id} not found"}

    counts = {}
    done_points = 0
    total_points = 0
    for t in tasks:
        counts[t["status"]] = counts.get(t["status"], 0) + 1
        total_points += t["points"] or 0
        if t["status"] == "done":
            done_points += t["points"] or 0

    lines = [
        f"*Sprint {sprint['name']}* ({sprint['start_date']} to {sprint['end_date']})",
        f"Tasks: {len(tasks)}",
        f"Points done: {done_points}/{total_points}",
    ]
    for status, n in sorted(counts.items()):
        lines.append(f"- {status}: {n}")

    blockers = []
    if include_blockers:
        blockers = [t for t in tasks if t["blocked"]]
        if blockers:
            lines.append("Blocked tasks:")
            for t in blockers:
                lines.append(f"  #{t['id']} {t['title']}")

    resp = requests.post(webhook_url, json={"text": "\n".join(lines)}, timeout=10)
    return {
        "ok": resp.status_code == 200,
        "status_code": resp.status_code,
        "sprint": sprint["name"],
        "task_count": len(tasks),
        "blocked_listed": len(blockers),
    }

import sqlite3
from datetime import datetime, timezone
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("project-tasks")

DB_PATH = "projects.db"
VALID_STATUSES = {"todo", "in_progress", "review", "done"}


@mcp.tool()
def update_task_details(task_id: int, title: str = None, status: str = None,
                        points: int = None, assignee: str = None) -> dict:
    if status is not None and status not in VALID_STATUSES:
        return {"ok": False, "error": f"Invalid status '{status}'"}
    if points is not None and points < 0:
        return {"ok": False, "error": "Points must be non-negative"}

    changes = {
        "title": title,
        "status": status,
        "points": points,
        "assignee": assignee,
    }
    changes = {k: v for k, v in changes.items() if v is not None}
    if not changes:
        return {"ok": False, "error": "No fields provided"}

    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        row = conn.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone()
        if row is None:
            return {"ok": False, "error": f"Task {task_id} not found"}

        now = datetime.now(timezone.utc).isoformat()
        set_clause = ", ".join(f"{k} = ?" for k in changes)
        conn.execute(
            f"UPDATE tasks SET {set_clause}, updated_at = ? WHERE id = ?",
            (*changes.values(), now, task_id),
        )
        for field, new_value in changes.items():
            conn.execute(
                "INSERT INTO task_history (task_id, field, old_value, new_value, changed_at) "
                "VALUES (?, ?, ?, ?, ?)",
                (task_id, field, str(row[field]), str(new_value), now),
            )
        conn.commit()
    finally:
        conn.close()

    return {"ok": True, "task_id": task_id, "updated": changes, "updated_at": now}
